{
  "gate_token": "v87QKkyNTri1zLPn2Accbw",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map at the broken city's edge.",
      "guidance": "Open on the ruined skyline at dusk.",
      "visual_description": "A tired mapmaker in an ink-stained coat kneels on cracked cobblestones, brass compass spinning, the ruined royal city smoking on the horizon behind her.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false invitations.",
      "visual_description": "A battered oil lamp sits on the map, its single flame-eye glowing as it leans toward Mara, casting long shadows across the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox is wound up and sent ahead.",
      "visual_description": "A small clockwork fox with blue glass eyes stretches as its key-wind tail clicks, poised at the mouth of a rubble-choked avenue beneath torn royal banners.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The castle gates loom, too open to be safe.",
      "visual_description": "Massive iron gates yawn wide under a cracked archway, faded crests above; Tin Fox's tiny silhouette pauses at the threshold.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Glass Diver steps out of a shattered window.",
      "visual_description": "A figure in a clear diving helmet emerges from a broken pane as if from water, coat shimmering with reflected lantern light and falling glass shards.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Mara and Glass Diver meet beneath a cursed tower.",
      "visual_description": "A leaning black tower drips green light; Mara holds up her compass while Glass Diver's helmet mirrors the tower back at itself.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp names the true prisoner's location.",
      "visual_description": "Lamp hovers over the unrolled map, its eye-flame pointing a beam at a marked chamber deep inside the palace ruins.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox scouts an armored patrol from a gutter.",
      "visual_description": "Reflections of plated boots and pike-shafts pass across Tin Fox's blue glass eyes as it crouches behind a fallen statue.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "They find the tax collector asleep at his post.",
      "visual_description": "A plump official slumps over a ledger pillow, stamped papers fluttering from his sleeves; Mara stares in disbelief while Tin Fox sniffs his shoe.",
      "characters": ["mara_the_cartographer", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a winged beast rattle distant windows.",
      "visual_description": "A vast shadow with horned wings passes over stained glass; Glass Diver presses a gloved hand to the pane, unimpressed, while the lamp's eye narrows.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "A magic door demands a name no one will say.",
      "visual_description": "An obsidian door covered in turning sigils blocks a corridor; Mara writes a false name in chalk while the lamp whispers the real one only to her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "Glass Diver slips through a tall mirror.",
      "visual_description": "Ripples spread across a gilt-framed mirror as Glass Diver dives in headfirst, coat-tails breaking the silver surface into bright fragments.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox finds the prisoner behind a tapestry.",
      "visual_description": "Behind a half-burned royal tapestry, Tin Fox's lantern-eyes illuminate chains coiled around an empty chair, a single warm cloak left behind.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The tax collector mutters in his sleep, revealing a passage.",
      "visual_description": "The dozing official drools onto his ledger; the page he sleeps on shows a hidden tunnel, ink bleeding into the shape of a stair.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Alarm bells ring across the ruined squares.",
      "visual_description": "Cracked bell towers shudder above empty plazas; Mara and Glass Diver run across moonlit flagstones while Tin Fox sprints ahead trailing sparks.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The oracle lamp points to the bridge.",
      "visual_description": "From a parapet, Lamp's flame-eye projects a thin gold line toward a long stone bridge arcing over a black river of fog.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the collapsing bridge.",
      "visual_description": "Glass Diver carries the rescued cloak-bundle, Mara grips the lamp, Tin Fox leaps gap to gap as stones tumble into mist below.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, the city burns behind them.",
      "visual_description": "On a grassy ridge, Mara folds her map, Glass Diver's helmet reflects the distant fires, Tin Fox sits with tail ticking, Lamp's eye dims to a soft ember.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

